UPDATE orders SET o_orderdate = o_orderdate + INTERVAL '1 year' WHERE o_orderkey IN (SELECT DISTINCT l.l_orderkey FROM lineitem l JOIN part p ON p.p_partkey = l.l_partkey JOIN partsupp ps ON ps.ps_partkey = l.l_partkey AND ps.ps_suppkey = l.l_suppkey JOIN supplier s ON s.s_suppkey = l.l_suppkey JOIN nation n ON n.n_nationkey = s.s_nationkey WHERE p.p_name LIKE '%green%' ORDER BY l.l_orderkey LIMIT 12);
